functions.\"Learner\".guard_finalized_journal_mont:
CREATE OR REPLACE FUNCTION "Learner".guard_finalized_journal_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    old_learner_id BIGINT;
    old_month TEXT;
    new_learner_id BIGINT;
    new_month TEXT;
    scope RECORD;
    latest_event TEXT;
BEGIN
    IF TG_TABLE_NAME = 'manual_activity_documents' THEN

        IF TG_OP <> 'INSERT' THEN
            SELECT j.learner_id, j.month
            INTO STRICT old_learner_id, old_month
            FROM "Learner".learner_journal_rows j
            WHERE j.id = OLD.manual_activity_id
              AND j.learner_id = OLD.learner_id;
        END IF;

        IF TG_OP <> 'DELETE' THEN
            SELECT j.learner_id, j.month
            INTO STRICT new_learner_id, new_month
            FROM "Learner".learner_journal_rows j
            WHERE j.id = NEW.manual_activity_id
              AND j.learner_id = NEW.learner_id;
        END IF;

    ELSE

        IF TG_OP <> 'INSERT' THEN
            old_learner_id := OLD.learner_id;
            old_month := OLD.month;
        END IF;

        IF TG_OP <> 'DELETE' THEN
            new_learner_id := NEW.learner_id;
            new_month := NEW.month;
        END IF;

    END IF;

    IF TG_OP <> 'INSERT'
       AND (old_learner_id IS NULL OR old_month IS NULL)
    THEN
        RAISE EXCEPTION 'Invalid old journal scope';
    END IF;

    IF TG_OP <> 'DELETE'
       AND (new_learner_id IS NULL OR new_month IS NULL)
    THEN
        RAISE EXCEPTION 'Invalid new journal scope';
    END IF;

    FOR scope IN
        SELECT DISTINCT
            v.learner_id,
            v.report_month
        FROM (
            VALUES
                (old_learner_id, old_month),
                (new_learner_id, new_month)
        ) AS v(learner_id, report_month)
        JOIN "Learner".learners l
            ON l.id = v.learner_id
        ORDER BY v.learner_id, v.report_month
    LOOP

        PERFORM pg_advisory_xact_lock(hashtextextended(
            'canonical-journal-finalization:' || scope.learner_id::text || ':' || scope.report_month, 0));

        SELECT e.event_type
        INTO latest_event
        FROM "Learner".manual_month_finalization_events e
        WHERE e.learner_id = scope.learner_id
          AND e.report_month = scope.report_month
        ORDER BY e.id DESC
        LIMIT 1;

        IF latest_event = 'finalized' THEN
            RAISE EXCEPTION USING
                ERRCODE = '55000',
                MESSAGE =
                    'Journal month is finalized and read-only: '
                    || scope.learner_id::TEXT
                    || '/'
                    || scope.report_month;
        END IF;

    END LOOP;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$function$

functions.\"Learner\".link_journal_kbc_progress():
CREATE OR REPLACE FUNCTION "Learner".link_journal_kbc_progress()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner_id bigint;
    existing_deleted_at timestamptz;
BEGIN
    IF NEW.progress_id IS NOT NULL OR coalesce(NEW.source_ref, '') NOT LIKE 'att:%' THEN
        RETURN NEW;
    END IF;
    SELECT id INTO owner_id FROM "Learner".learners WHERE aptem_id=NEW.aptem_id;
    IF owner_id IS NULL THEN RETURN NEW; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('learner-journal-progress'), owner_id::integer);
    SELECT p.id, p.deleted_at INTO NEW.progress_id, existing_deleted_at
    FROM "Learner".learner_progress_entries p
    WHERE p.learner_id=owner_id AND (
        p.kbc_attendance_key=substring(NEW.source_ref FROM 5) OR
        p.source_payload->>'original_source_ref'=NEW.source_ref)
    ORDER BY (p.deleted_at IS NULL) DESC, p.id LIMIT 1;
    IF NEW.progress_id IS NOT NULL THEN
        NEW.learner_id := owner_id;
        NEW.deleted_at := existing_deleted_at;
    END IF;
    RETURN NEW;
END
$function$

functions.\"Learner\".guard_new_month_status():
CREATE OR REPLACE FUNCTION "Learner".guard_new_month_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.month_status IS DISTINCT FROM 'open' THEN
        RAISE EXCEPTION
            'New monthly targets must start with open status';
    END IF;

    RETURN NEW;
END;
$function$

functions.\"Learner\".link_existing_monthly_signat:
CREATE OR REPLACE FUNCTION "Learner".link_existing_monthly_signatures()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    target_ids BIGINT[];
BEGIN
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            NEW.learner_id::text
            || ':' || NEW.report_month,
            0
        )
    );

    SELECT ARRAY_AGG(id ORDER BY id)
    INTO target_ids
    FROM "Learner".learner_monthly_targets
    WHERE learner_id = NEW.learner_id
      AND report_month = NEW.report_month;

    IF COALESCE(CARDINALITY(target_ids), 0) > 1 THEN
        RAISE EXCEPTION
            'Multiple monthly targets found';
    END IF;

    UPDATE "Learner".learner_monthly_signatures
    SET monthly_target_id = NEW.id
    WHERE learner_id = NEW.learner_id
      AND report_month = NEW.report_month
      AND monthly_target_id IS NULL
      AND source_system = 'lms'
      AND source_ref LIKE 'lms-monthly:%';

    RETURN NEW;
END;
$function$

functions.\"Learner\".link_progress_kbc_attendance:
CREATE OR REPLACE FUNCTION "Learner".link_progress_kbc_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner_aptem_id bigint;
    candidate_key text;
BEGIN
    IF NEW.kbc_attendance_key IS NULL
       AND coalesce(
           NEW.source_payload->>'original_source_ref', ''
       ) NOT LIKE 'att:%'
    THEN
        RETURN NEW;
    END IF;

    SELECT aptem_id INTO owner_aptem_id
    FROM "Learner".learners
    WHERE id = NEW.learner_id;

    IF NEW.kbc_attendance_key IS NOT NULL THEN

        IF NOT EXISTS (
            SELECT 1
            FROM "Learner".source_lms_attendance a
            WHERE a.source_key = NEW.kbc_attendance_key
              AND a.learner_id = NEW.learner_id
              AND a.aptem_id = owner_aptem_id
        )
        THEN
            RAISE EXCEPTION
                'Attendance key does not belong to this learner'
                USING ERRCODE = '23503';
        END IF;

    ELSIF NEW.source_payload->>'original_source_ref'
          LIKE 'att:%' THEN

        candidate_key := substring(
            NEW.source_payload->>'original_source_ref'
            FROM 5
        );

        SELECT a.source_key INTO NEW.kbc_attendance_key
        FROM "Learner".source_lms_attendance a
        WHERE a.source_key = candidate_key
          AND a.learner_id = NEW.learner_id
          AND a.aptem_id = owner_aptem_id;

    END IF;

    RETURN NEW;
END;
$function$
